const visual = {
  prepare: function (input) {
    return [];
  },
  render: function (input, metrics) {
    var w = input.viewport.widthDu;
    var h = input.viewport.heightDu;
    var cols = 4;
    var rows = 3;
    var margin = Math.min(w, h) * 0.12;
    var availW = w - margin * 2;
    var availH = h - margin * 2;
    var cell = Math.min(availW / cols, availH / rows);
    var gridW = cell * cols;
    var gridH = cell * rows;
    var x0 = (w - gridW) / 2;
    var y0 = (h - gridH) / 2;
    var cmds = [];
    var c, r, x, y;
    for (c = 0; c <= cols; c++) {
      x = x0 + c * cell;
      cmds.push(['M', x, y0]);
      cmds.push(['L', x, y0 + gridH]);
    }
    for (r = 0; r <= rows; r++) {
      y = y0 + r * cell;
      cmds.push(['M', x0, y]);
      cmds.push(['L', x0 + gridW, y]);
    }
    return {
      schemaVersion: 1,
      sceneId: 'grid-3x4',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: w, height: h },
      paths: [{ id: 'grid', commands: cmds }],
      root: {
        type: 'group',
        children: [
          {
            type: 'path',
            pathId: 'grid',
            fill: '#26354a',
            stroke: { width: 2, cap: 'round', join: 'round' }
          }
        ]
      }
    };
  }
};
